from flask import Flask
import app_header as site
import ui_final

ui_final.install(site)

# Exact BUZENT mark embedded directly so Vercel cannot lose the asset.
BUZENT_MARK = "data:image/webp;base64,"

@site.app.after_request
def _buzent_logo_and_hub_fix(response):
    ctype = response.headers.get('Content-Type', '')
    if 'text/html' not in ctype:
        return response
    html = response.get_data(as_text=True)
    html = html.replace('<img class="bzExactLogo" src="/static/buzent-logo.webp" alt="BUZENT">',
                        '<span class="embeddedBrand"><img src="'+BUZENT_MARK+'" alt="BUZENT logo"><span class="embeddedWord">BU<span>Z</span>ENT</span></span>')
    html = html.replace('<img class="hubExactLogo" src="/static/buzent-logo.webp" alt="BUZENT">',
                        '<span class="hubBrand"><img src="'+BUZENT_MARK+'" alt="BUZENT logo"><span class="hubWord">BU<span>Z</span>ENT</span></span>')
    html = html.replace('<small>GLOBAL CONNECTION PLATFORM</small>', '')
    css = '''<style>
    .embeddedBrand{display:flex;align-items:center;gap:10px}.embeddedBrand img{width:48px;height:48px;object-fit:contain;border-radius:8px}.embeddedWord{font-family:Manrope,sans-serif;font-size:23px;font-weight:800;letter-spacing:.16em;color:#fff;white-space:nowrap}.embeddedWord>span,.hubWord>span{color:#D99A20}.finalBrand{min-width:215px!important;height:auto!important}.finalBrand .bzExactLogo{display:none!important}
    .finalHub{display:flex!important;flex-direction:column;align-items:center;justify-content:center!important;overflow:hidden!important;padding:18px!important}.hubOfficial{width:100%!important;display:flex!important;align-items:center!important;justify-content:center!important}.hubBrand{width:150px;height:150px;border-radius:50%;background:#fff;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;padding:14px;box-shadow:0 0 0 1px rgba(255,255,255,.18),0 10px 30px rgba(0,0,0,.22)}.hubBrand img{width:88px;height:88px;object-fit:contain}.hubWord{font-family:Manrope,sans-serif;font-size:15px;font-weight:800;letter-spacing:.13em;color:#071A33;line-height:1}.finalHub small{display:none!important}
    @media(max-width:760px){.embeddedBrand img{width:40px;height:40px}.embeddedWord{font-size:18px}.hubBrand{width:122px;height:122px;padding:10px}.hubBrand img{width:70px;height:70px}.hubWord{font-size:12px}}
    </style>'''
    html = html.replace('</head>', css+'</head>')
    response.set_data(html)
    return response

# Literal Flask application for Vercel Python runtime detection.
app = Flask(__name__)
app.wsgi_app = site.app.wsgi_app
application = app
